-- Generated by `theme` for {{ theme.name }}; edit ~/.config/theme, not this file.
hl.config({
	general = {
		gaps_in = {{ look.gaps_in }},
		gaps_out = {{ look.gaps_out }},
		border_size = {{ look.border_size }},
		layout = "{{ look.tiling }}",
		col = {
			active_border = { colors = { {% for role in look.border %}"{{ p[role] | hypr }}"{{ ", " if not loop.last }}{% endfor %} }, angle = {{ look.border_angle }} },
			inactive_border = "{{ p[look.inactive_border] | hypr }}",
		},
	},
	decoration = {
		rounding = {{ look.rounding }},
		blur = { enabled = {{ look.blur | lua }} },
		shadow = { enabled = {{ look.shadow | lua }}, color = "{{ p.bg_dark | hypr(0xaa) }}" },
	},
	animations = { enabled = {{ (look.animations != "none") | lua }} },
})
{% if look.animations == "bouncy" %}

hl.curve("theme", { type = "bezier", points = { { 0.05, 0.9 }, { 0.10, 1.05 } } })
hl.curve("overshot", { type = "bezier", points = { { 0.13, 0.99 }, { 0.29, 1.10 } } })
hl.animation({ leaf = "windows", enabled = true, speed = 3, bezier = "theme" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 5, bezier = "theme" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 5, bezier = "theme" })
hl.animation({ leaf = "border", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "fade", enabled = true, speed = 5, bezier = "default" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, bezier = "overshot", style = "slidevert" })
{% elif look.animations == "smooth" %}

hl.curve("theme", { type = "bezier", points = { { 0.25, 1.0 }, { 0.5, 1.0 } } })
hl.animation({ leaf = "windows", enabled = true, speed = 4, bezier = "theme", style = "popin 90%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 4, bezier = "theme", style = "popin 90%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 4, bezier = "theme" })
hl.animation({ leaf = "border", enabled = true, speed = 8, bezier = "default" })
hl.animation({ leaf = "fade", enabled = true, speed = 4, bezier = "default" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, bezier = "theme", style = "fade" })
{% endif %}
